from __future__ import annotations

from typing import Protocol, TypedDict, NotRequired, runtime_checkable
from dataclasses import dataclass

type UserId = str
type Result[T] = tuple[T, None] | tuple[None, str]

class UserDto(TypedDict):
    id: UserId
    name: str
    email: NotRequired[str]

class UserRepo(Protocol):
    async def get(self, user_id: UserId) -> UserDto | None: ...
    async def save(self, user: UserDto) -> None: ...

def first[T](items: list[T]) -> T | None:
    return items[0] if items else None

@dataclass(frozen=True, slots=True)
class User:
    id: UserId
    name: str

def to_dto(user: User) -> UserDto:
    return {"id": user.id, "name": user.name}

# PEP 695 generic class
class Cache[K, V]:
    def __init__(self) -> None:
        self._data: dict[K, V] = {}
    def get(self, key: K) -> V | None:
        return self._data.get(key)
